head.script:
scwin.onpageload = function() {
    var row = 10;
    var col = 3;
    var data = [];
    var data2 = [];
    for (var i = 0; i < row; i++) {
        for (var j = 0; j < col; j++) {
            data.push(i * col + j);
            data2.push(String(i * col + j));
            data2.push(String(i * col + j));
        }
    }
    dataList2.setData(data2);
    dataList1.setData(data);
};
scwin.onpageunload = function() {};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#G_gridView1___autoComplete_0_col2_col2_input', 'keydown', {
        keyCode: 13,
        which: 13,
        key: 'ENTER'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플실행 후 'col2'항목의 첫번째 row('1'값)를 마우스로 더블클릭하여 edit모드로 진입한다.
    //1. After executing the sample, double click the first row ('1' value) of 'col2' item to enter edit mode.
    //Verify step 1. The first row enters edit mode.
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_gridView1___autoComplete_0_col2_col2_input').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. '5'값으로 변경 후 EnterKey를 누른다.
    //2. Change to the value '5' and press EnterKey.
    //Verify step 2. Change to the value '5' (not previously changed to EnterKey).
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#G_gridView1___autoComplete_0_col2_col2_input').val('5')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_1').text() == '5'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 다시 더블클릭하여 '50'을 입력하고 EnterKey를 누른다.
    //3. Double click again to enter '50' and press EnterKey.
    //Verify step 3. Change to the value '50' (not previously changed to EnterKey).
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'gridView1_cell_0_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#G_gridView1___autoComplete_0_col2_col2_input').val('50')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_1').text() == '50'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 30-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
